import type { OptimizationMode } from "../specification/types.js";
export interface SpreadsheetRow { rowNumber?: number; block_type: string; block_id: string; field: string; value: string; aesthetic?: string; maximum_visibility?: string; maximum_clicks?: string; maximum_revenue?: string; notes?: string; }
export type ParsedBlocks = Record<string, Record<string, Record<string, string>>>;
const modeColumn: Record<OptimizationMode, keyof SpreadsheetRow> = { aesthetic: "aesthetic", "maximum-visibility": "maximum_visibility", "maximum-clicks": "maximum_clicks", "maximum-revenue": "maximum_revenue" };
export function parseRows(rows: SpreadsheetRow[], mode: OptimizationMode): ParsedBlocks { const blocks: ParsedBlocks = {}; for (const row of rows) { if (!row.block_type || !row.block_id || !row.field) continue; const modeValue = String(row[modeColumn[mode]] ?? "on").toLowerCase(); if (["off","false","0","no"].includes(modeValue)) continue; const type = row.block_type.toUpperCase(); blocks[type] ??= {}; blocks[type][row.block_id] ??= {}; blocks[type][row.block_id][row.field] = row.value; } return blocks; }
export function normalizeRows(rows: SpreadsheetRow[]): string { return JSON.stringify(rows.map(r=>({block_type:r.block_type?.trim().toUpperCase(),block_id:r.block_id?.trim(),field:r.field?.trim(),value:String(r.value??""),aesthetic:r.aesthetic??"",maximum_visibility:r.maximum_visibility??"",maximum_clicks:r.maximum_clicks??"",maximum_revenue:r.maximum_revenue??""})).sort((a,b)=>JSON.stringify(a).localeCompare(JSON.stringify(b)))); }
